import { useEffect, useState } from 'react'
export default function Avaliacoes(){const [items,setItems]=useState([]);const carregar=()=>fetch('/api/avaliacoes').then(r=>r.json()).then(setItems);useEffect(()=>{carregar()},[]);const responder=async a=>{const resposta=prompt('Resposta ao cliente:',a.resposta||'');if(resposta===null)return;await fetch(`/api/avaliacoes/${a.id}/responder`,{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({resposta})});carregar()};return <div><div className="section-head"><div><h2>Avaliações</h2><div className="muted">Feedback dos pedidos finalizados</div></div></div><div style={{display:'grid',gap:12}}>{items.map(a=><div className="card" key={a.id}><div style={{display:'flex',justifyContent:'space-between'}}><strong>{a.cliente?.nome}</strong><span>{'★'.repeat(a.nota)}{'☆'.repeat(5-a.nota)}</span></div><div className="muted">Pedido #{a.pedido?.numero}</div><p>{a.comentario||'Sem comentário.'}</p>{a.resposta&&<div className="card" style={{marginTop:8}}>Resposta: {a.resposta}</div>}<button className="btn btn-ghost" onClick={()=>responder(a)}>Responder</button></div>)}</div>{!items.length&&<div className="card empty-state">Nenhuma avaliação ainda.</div>}</div>}
